/**
 * Service Worker - PWA Fallback
 *
 * NOTE: This is a minimal fallback service worker.
 * The actual production service worker is generated by @vite-pwa/nuxt module
 * using Workbox during the Nuxt build process.
 *
 * The module configuration is defined in nuxt.config.ts under the 'pwa' key.
 * See nuxt.config.ts for cache strategies, runtime caching policies, and update behavior.
 *
 * Authority: @vite-pwa/nuxt (module-driven)
 * Update strategy: autoUpdate with skipWaiting + clientsClaim (immediate activation)
 */

// Fallback lifecycle for development/offline scenarios
self.addEventListener("install", (event) => {
  console.log("[PWA] Service Worker install event");
  self.skipWaiting();
});

self.addEventListener("activate", (event) => {
  console.log("[PWA] Service Worker activate event");
  event.waitUntil(self.clients.claim());
});

self.addEventListener("fetch", (event) => {
  console.debug("[PWA] Fetch event", event.request.url);
});

self.addEventListener("message", (event) => {
  if (event.data?.type === "SKIP_WAITING") {
    self.skipWaiting();
  }
});
